const evt = $('New or interested reply').first().json;
const cfg = $('Owners').first().json;
const owners = typeof cfg.owners === 'string' ? JSON.parse(cfg.owners) : cfg.owners;
const tags = ($input.first().json.tags || []).map(t => String(t).toLowerCase());
const tag = tags.find(t => owners[t]);
return [{ json: { to: tag ? owners[tag] : cfg.default_owner, matched_tag: tag || null,
  campaign: $input.first().json.name, campaign_url: $input.first().json.url,
  lead_email: evt.lead_email, subject: evt.subject, snippet: evt.snippet,
  kind: evt.event === 'reply.positive' ? 'Interested reply' : 'New reply' } }];

